/* SPDX-License-Identifier: LGPL-2.1-or-later */

#include <string.h>

#include "alloc-util.h"
#include "strv.h"
#include "tests.h"

TEST(rebreak_lines_reset_onto_invalid_lead_byte) {
        /* After a line break the scan restarts at the first non-whitespace character, which here is a
         * truncated-looking 0xF0 lead byte followed by 'b' and NUL. The advance must not trust the lead
         * byte's skip length and step past the NUL. Exactly sized heap buffer so ASan/valgrind notice. */
        _cleanup_free_ char *s = memdup("a \xF0" "b", 5);
        ASSERT_NOT_NULL(s);

        char *l[] = { s, NULL };
        _cleanup_strv_free_ char **broken = NULL;

        ASSERT_OK(strv_rebreak_lines(l, 3, &broken));
        ASSERT_NOT_NULL(broken);
        ASSERT_GE(strv_length(broken), 1u);
}

DEFINE_TEST_MAIN(LOG_DEBUG);

